
// ══ AUDIO ══
const audBday=new Audio('data:audio/mpeg;base64,');
const audCin =new Audio('data:audio/mpeg;base64,');
audBday.loop=true; audCin.loop=true;
let curAud=null, mPlay=false;

async function playAud(aud,title,artist){
  if(curAud&&curAud!==aud){curAud.pause();curAud.currentTime=0;}
  curAud=aud;
  document.getElementById('mlbl').textContent=title;
  document.getElementById('msub').textContent='♫ '+artist;
  document.getElementById('mbar').classList.add('show');
  try{
    await aud.play(); mPlay=true;
    document.getElementById('mbtn').textContent='⏸';
  }catch(e){
    mPlay=false; document.getElementById('mbtn').textContent='▶';
  }
}
function toggleM(){
  if(!curAud)return;
  if(mPlay){curAud.pause();mPlay=false;document.getElementById('mbtn').textContent='▶';}
  else{curAud.play().then(()=>{mPlay=true;document.getElementById('mbtn').textContent='⏸';});}
}

// ══ PAGE NAV ══
let cur='p-intro';
function navTo(id){
  if(id===cur)return;
  const c=document.getElementById(cur);
  const n=document.getElementById(id);
  c.classList.add('exit');c.classList.remove('active');
  setTimeout(()=>{c.classList.remove('exit');n.classList.add('active');cur=id;},380);
}

// ══ HEARTS ══
const HE=['❤️','🩷','💕','💗','💖','🌸','✨','💘','🎀','🐰','🥕'];
function spawnHeart(){
  const el=document.createElement('span');el.className='heart';
  el.textContent=HE[Math.random()*HE.length|0];
  el.style.cssText=`left:${Math.random()*100}vw;font-size:${12+Math.random()*14}px;animation-duration:${7+Math.random()*8}s;animation-delay:${Math.random()*2}s`;
  document.getElementById('hl').appendChild(el);
  setTimeout(()=>el.remove(),20000);
}
setInterval(spawnHeart,750);

// ══ SPARKLES ══
const SE=['✨','💫','⭐','💕','🌸','🐰','🥕','🎉'];
function sparks(cx,cy){
  for(let i=0;i<7;i++) setTimeout(()=>{
    const el=document.createElement('span');el.className='sparkle';
    el.textContent=SE[Math.random()*SE.length|0];
    el.style.cssText=`left:${cx+(Math.random()-.5)*80}px;top:${cy+(Math.random()-.5)*80}px`;
    document.body.appendChild(el);setTimeout(()=>el.remove(),1000);
  },i*60);
}
document.body.addEventListener('click',e=>{if(Math.random()>.55)sparks(e.clientX,e.clientY);});

// ══ CONFETTI ══
const CC=['#FF1493','#FF4757','#FF69B4','#FFB6C1','#FF7A00','#FFF','#FFD700','#A8D5A2'];
function confetti(){
  for(let i=0;i<90;i++) setTimeout(()=>{
    const el=document.createElement('div');el.className='cpfetti';
    const s=6+Math.random()*10;
    el.style.cssText=`left:${Math.random()*100}vw;background:${CC[Math.random()*CC.length|0]};width:${s}px;height:${s}px;border-radius:${Math.random()>.5?'50%':'4px'};animation-duration:${2.4+Math.random()*2.8}s;animation-delay:${Math.random()*1.2}s`;
    document.body.appendChild(el);setTimeout(()=>el.remove(),5500);
  },i*22);
}

// ══ TYPEWRITER ══
function typeText(elId,txt,speed,cb){
  const el=document.getElementById(elId);if(!el)return;
  el.textContent='';let i=0;
  (function t(){
    if(i<txt.length){el.textContent+=txt[i++];setTimeout(t,speed);}
    else if(cb)setTimeout(cb,200);
  })();
}

